import { useCallback, useEffect, useState } from "react";
import CommonListViewTable from "../../../utils/CommonListViewTable";
import preDeliveryInspectionReportAPI from "../../../api/quality/preDeliveryInspectionReportAPI";
import { toast } from "../../../utils/toast";

const PreDeliveryInspectionReportList = ({
  onAddNew,
  onEdit,
  onBack,
  refreshTrigger,
}) => {
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(false);

  const ORG_ID = localStorage.getItem("orgId");
  const BRANCH_ID = localStorage.getItem("branchId");

  const loadRecords = useCallback(async () => {
    try {
      setLoading(true);
      const data =
        await preDeliveryInspectionReportAPI.getPreDeliveryInspectionReportByOrgId(
          ORG_ID,
          BRANCH_ID,
        );
      data.sort((a, b) => (b.id || 0) - (a.id || 0));
      setRecords(data);
    } catch (error) {
      console.error("Failed to load pre-delivery inspection reports:", error);
      setRecords([]);
      toast.error("Failed to fetch Pre-Delivery Inspection Reports");
    } finally {
      setLoading(false);
    }
  }, [ORG_ID, BRANCH_ID]);

  useEffect(() => {
    loadRecords();
  }, [loadRecords, refreshTrigger]);

  const columns = [
    {
      key: "transferSlipNo",
      label: "Transfer Slip No",
      accessor: (row) => row.transferSlipNo,
      type: "text",
      noWrap: true,
    },
    {
      key: "date",
      label: "Date",
      accessor: (row) => row.date,
      type: "text",
    },
    {
      key: "plantId",
      label: "Plant",
      accessor: (row) =>
        typeof row.plantId === "object"
          ? row.plantId.branchName || row.plantId.id
          : row.plantName || row.plantId,
      type: "text",
    },
    {
      key: "belongsTo",
      label: "Belongs To",
      accessor: (row) => row.belongsTo,
      type: "text",
    },
    {
      key: "itemCode",
      label: "Item Code",
      accessor: (row) =>
        typeof row.itemCode === "object"
          ? row.itemCode.itemCode || row.itemCode.id
          : row.itemCode,
      type: "text",
    },
    {
      key: "itemDescription",
      label: "Item Description",
      accessor: (row) =>
        typeof row.itemDescription === "object"
          ? row.itemDescription.itemDescription
          : row.itemDescription,
      type: "text",
    },
    {
      key: "customerCode",
      label: "Customer Code",
      accessor: (row) =>
        typeof row.customerCode === "object"
          ? row.customerCode.customerCode || row.customerCode.id
          : row.customerCode,
      type: "text",
    },
    {
      key: "customerName",
      label: "Customer Name",
      accessor: (row) =>
        typeof row.customerCode === "object"
          ? row.customerCode.customerName
          : row.customerName,
      type: "text",
    },
    {
      key: "producedQty",
      label: "Produced Qty",
      accessor: (row) => row.producedQty,
      type: "text",
    },
    {
      key: "active",
      label: "Status",
      accessor: "active",
      type: "status",
      statusVariants: {
        Active: {
          label: "Active",
          className:
            "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300",
        },
        Inactive: {
          label: "Inactive",
          className:
            "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300",
        },
      },
    },
    {
      key: "actions",
      label: "Actions",
      type: "actions",
      align: "center",
      width: "90px",
    },
  ];

  const searchFields = [
    "transferSlipNo",
    "date",
    "plantId",
    "plantId.branchName",
    "plantName",
    "belongsTo",
    "itemCode",
    "itemCode.itemCode",
    "itemDescription",
    "itemDescription.itemDescription",
    "customerCode",
    "customerCode.customerCode",
    "customerName",
    "producedQty",
    "productionScheduleOrderNo",
  ];

  const filterOptions = [
    { value: "all", label: "All", field: null },
    {
      value: "active",
      label: "Active",
      field: "active",
      filterValue: "active",
      activeValue: "Active",
    },
    {
      value: "inactive",
      label: "Inactive",
      field: "active",
      filterValue: "inactive",
      activeValue: "Active",
    },
  ];

  return (
    <CommonListViewTable
      title="Pre-Delivery Inspection Report"
      data={records}
      loading={loading}
      columns={columns}
      searchFields={searchFields}
      filterOptions={filterOptions}
      defaultFilter="all"
      onBack={onBack}
      onAddNew={onAddNew}
      onEdit={onEdit}
      onView={false}
      showSerialNumber={true}
      itemsPerPageOptions={[5, 10, 20, 50, 100]}
      defaultItemsPerPage={10}
      emptyMessage="No Pre-Delivery Inspection Reports found"
      loadingMessage="Loading Pre-Delivery Inspection Reports..."
      enableRefresh={true}
      onRefresh={loadRecords}
      enableExport={true}
      exportFileName="PreDeliveryInspectionReports"
    />
  );
};

export default PreDeliveryInspectionReportList;
