import { useCallback, useState } from "react";
import { useNavigate } from "react-router-dom";
import PurchaseContractAmendmentForm from "./PurchaseContractAmendmentForm";
import PurchaseContractAmendmentList from "./PurchaseContractAmendmentList";
import purchaseContractAmendmentAPI from "../../../api/Purchase/purchaseContractAmendmentAPI";
import { toast } from "../../../utils/toast";

const PurchaseContractAmendmentMaster = () => {
  const navigate = useNavigate();
  const [view, setView] = useState("list"); // "list" | "form"
  const [editData, setEditData] = useState(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  const ORG_ID = localStorage.getItem("orgId");
  const BRANCH_ID = localStorage.getItem("branchId");

  const handleAddNew = () => {
    setEditData(null);
    setView("form");
  };

  // Pencil icon click -> fetch fresh data by orgId, find the matching record, open form
  const handleEdit = useCallback(
    async (row) => {
      try {
        const records = await purchaseContractAmendmentAPI.getAll(ORG_ID, BRANCH_ID);
        const fresh = records.find((r) => r.id === row.id) || row;
        setEditData(fresh);
        setView("form");
      } catch (error) {
        console.error("Failed to fetch PC amendment for edit:", error);
        toast.error("Failed to load PC amendment details");
      }
    },
    [ORG_ID, BRANCH_ID],
  );

  const handleBack = () => {
    setEditData(null);
    setView("list");
    // bump refreshTrigger so the list re-fetches after add/update
    setRefreshTrigger((prev) => prev + 1);
  };

  // List screen back button -> return to the Purchase module home.
  // (Form's back button goes back to the list via handleBack.)
  const handleNavigateHome = () => {
    navigate("/purchase");
  };

  if (view === "form") {
    return <PurchaseContractAmendmentForm data={editData} onBack={handleBack} />;
  }

  return (
    <PurchaseContractAmendmentList
      onAddNew={handleAddNew}
      onEdit={handleEdit}
      onBack={handleNavigateHome}
      refreshTrigger={refreshTrigger}
    />
  );
};

export default PurchaseContractAmendmentMaster;
