import { useState } from "react";
import ScreenNamesList from "./ScreenNamesList";
import ScreenNamesForm from "./ScreenNamesForm";
import screensAPI from "../../../api/screensAPI";

const ScreenNames = () => {
    const [screen, setScreen] = useState("list");
    const [editData, setEditData] = useState(null);

    const addNew = () => {
        console.log("Add button clicked");
        setEditData(null);
        setScreen("form");
    };

    const edit = (row) => {
        console.log("Edit clicked:", row);
        setEditData(row);
        setScreen("form");
    };

    const handleBack = () => {
        setScreen("list");
    };

    const handleSave = async (payload) => {
        try {
            if (payload.id) {
                // Update existing screen
                await screensAPI.updateScreen(payload.id, payload);
            } else {
                // Create new screen
                await screensAPI.createScreen(payload);
            }
            handleBack();
        } catch (error) {
            console.error("Error saving screen:", error);
            throw error;
        }
    };

    return (
        <>
            {screen === "list" && (
                <ScreenNamesList
                    onAddNew={addNew}
                    onEdit={edit}
                    onBack={() => window.history.back()}
                />
            )}

            {screen === "form" && (
                <ScreenNamesForm
                    data={editData}
                    onBack={handleBack}
                    onSave={handleSave}
                />
            )}
        </>
    );
};

export default ScreenNames;