// ============================================================
// ITEM COLOR PALETTE
// ============================================================

const ITEM_COLOR_PALETTE = [
  "blue",
  "cyan",
  "teal",
  "indigo",
  "amber",
  "rose",
  "purple",
  "pink",
  "orange",
  "emerald",
  "sky",
  "violet",
  "fuchsia",
  "lime",
  "red",
  "yellow",
];

// ============================================================
// QUALITY LIST
// ============================================================

const QualityList = () => {
  const navigate = useNavigate();

  const userType = localStorage.getItem("userType")?.toUpperCase();

  let colorIndex = 0;

  const filteredSections = SECTIONS.map((section) => ({
    ...section,

    items: section.items
      .filter((item) => {
        if (userType === "SADMIN") return false;

        return hasScreenAccess(item.screenCode);
      })
      .map((item) => ({
        ...item,

        color: ITEM_COLOR_PALETTE[colorIndex++ % ITEM_COLOR_PALETTE.length],
      })),
  })).filter((section) => section.items.length > 0);

  const hasAnyItems = filteredSections.some(
    (section) => section.items.length > 0,
  );

  return (
    <div
      className="animate-fadeIn px-3 py-3"
      style={{
        transform: "scale(0.98)",
        transformOrigin: "top left",
      }}
    >
      {hasAnyItems ? (
        <>
          {/* ======================================================
              MAIN HEADING
          ====================================================== */}

          {/* <div className="flex items-center gap-2 mb-5">
            <div className="p-1.5 rounded-lg bg-gradient-to-br from-cyan-600 to-sky-500 shadow-sm">
              <ClipboardCheck className="h-4 w-4 text-white" />
            </div>

            <h2 className="text-base font-semibold text-gray-900 dark:text-white">
              Quality
            </h2>

            <span className="text-xs text-gray-500 dark:text-gray-400 ml-2">
              Manage inspections, quality assurance, vendor quality, calibration
              and quality reports
            </span>

            <div className="flex-1 h-px bg-gradient-to-r from-gray-200 to-transparent dark:from-gray-700"></div>
          </div> */}

          {/* ======================================================
              MASTERS + TRANSACTION SECTIONS
          ====================================================== */}

          {filteredSections.map((section, sectionIndex) => {
            const SectionIcon = section.icon;

            return (
              <div
                key={section.title || `section-${sectionIndex}`}
                className="mb-6"
              >
                {/* ==================================================
                    SUB HEADING
                ================================================== */}

                {section.title && (
                  <div className="flex items-center gap-2 mb-3">
                    {SectionIcon && (
                      <div
                        className={`p-1.5 rounded-md bg-gradient-to-br ${
                          section.gradient || "from-blue-600 to-cyan-500"
                        } shadow-sm`}
                      >
                        <SectionIcon className="h-3.5 w-3.5 text-white" />
                      </div>
                    )}

                    <h3
                      className={`text-sm font-semibold ${
                        getColorStyles(section.color || "blue").text
                      }`}
                    >
                      {section.title}
                    </h3>

                    {section.description && (
                      <span className="text-[11px] text-gray-500 dark:text-gray-400">
                        {section.description}
                      </span>
                    )}

                    <div className="flex-1 h-px bg-gradient-to-r from-gray-200 to-transparent dark:from-gray-700"></div>
                  </div>
                )}

                {/* ==================================================
                    CARDS
                ================================================== */}

                <div className="grid grid-cols-6 sm:grid-cols-7 lg:grid-cols-9 xl:grid-cols-10 2xl:grid-cols-12 gap-3">
                  {section.items.map((item, itemIndex) => {
                    const ItemIcon = item.icon;
                    const colors = getColorStyles(item.color || "blue");

                    return (
                      <div
                        key={item.name}
                        role="link"
                        tabIndex={0}
                        onClick={() => navigate(item.path)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" || e.key === " ") {
                            e.preventDefault();
                            navigate(item.path);
                          }
                        }}
                        className="group cursor-pointer animate-slideUp"
                        style={{
                          animationDelay: `${
                            (sectionIndex * 6 + itemIndex) * 30
                          }ms`,
                        }}
                      >
                        <div
                          className={`
                            relative overflow-hidden
                            bg-white dark:bg-gray-800
                            rounded-lg
                            border border-gray-200 dark:border-gray-700
                            ${colors.border}
                            ${colors.hover}
                            transition-all duration-200
                            hover:shadow-md
                            hover:scale-[1.02]
                          `}
                        >
                          <div className="p-1 h-20 flex flex-col items-center justify-center text-center">
                            <div
                              className={`
                                p-2 rounded-lg
                                ${colors.iconBg}
                                transition-all duration-200
                                group-hover:scale-105
                                mb-1.5
                              `}
                            >
                              <ItemIcon className={`h-4 w-4 ${colors.text}`} />
                            </div>

                            <h3
                              className={`
                                text-xs font-medium
                                ${colors.text}
                                transition-colors
                                leading-tight
                                line-clamp-2
                              `}
                            >
                              {item.name}
                            </h3>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </>
      ) : (
        <div className="flex items-center justify-center h-[50vh]">
          <div className="text-center">
            <h2 className="text-base font-semibold text-gray-800 dark:text-white">
              No quality modules available
            </h2>

            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
              You do not have access to any quality module.
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

// ============================================================
// SHARED ENTRANCE ANIMATIONS
// ============================================================

const styles = `
  @keyframes fadeIn {
    from {
      opacity: 0;
    }

    to {
      opacity: 1;
    }
  }

  @keyframes slideUp {
    from {
      opacity: 0;
      transform: translateY(10px);
    }

    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .animate-fadeIn {
    animation: fadeIn 0.4s ease-out;
  }

  .animate-slideUp {
    animation: slideUp 0.3s ease-out forwards;
    opacity: 0;
  }
`;

if (typeof document !== "undefined") {
  const styleSheet = document.createElement("style");

  styleSheet.textContent = styles;

  document.head.appendChild(styleSheet);
}

export default QualityList;
